//! The PLL: VCO range, SEL_DIV dividers, the reference rule, the Nint
//! runs that locked, R2 VCO_INDICATOR, and the LO spans reachable.
//!
//! Method (findings.md steps 4c, 4d): the sweep programmed every SEL_DIV
//! code x Nint 13..=268 in steps of 5 (Nfra 0, REF_DIV2 1), read R0-R4,
//! then placed the tone at the RF each divider hypothesis predicts
//! (f_LO = f_ref * 2 * (Nint + Nfra) / divider, RF = LO - 4.57 MHz) and
//! read `if_agc_val` MSB-first in the vagc configuration. A setting is
//! "received" when that reading is at or below 1000 counts (the
//! full-strength
//! readings are at most 633, the partial ones at least 1844). The
//! undescribed codes 100-111 had the PLL held at Nint 88 and the tone
//! stepped across 2-1298 MHz in 3 MHz steps (lo-find); the LO is the
//! full-strength run's centre plus the IF (the wanted sideband is below
//! the LO, step 4h) and the divider is f_VCO / LO rounded to a power of
//! two. A sweep run may pass through a setting that read partially (at
//! most 6000 counts); its bounds are its first and last full-strength
//! settings.
//!
//! Resolution: the sweep's Nint step is 5 (f_VCO steps of 144 MHz), so a
//! run's edges are known to one step; lo-find's RF step is 3 MHz.
//!
//! Caveats: the /1 code could not be tested (its LO is above the source's
//! 6 GHz); the VCO range is the documented codes' received bounds and the
//! driver's `VCO_RANGE_HZ` sits 30 MHz inside them by choice; no SEL_DIV
//! code reaches the LO span in `LO_UNREACHABLE_HZ` (RF about 110-208 MHz
//! with a 4.57 MHz IF) — whether the VCO runs lower under settings the
//! sweep did not vary (R24/R25/R28/R31 unspecified cells, the LDO
//! voltages, PW_SDM, CAPX) is an open search, not assumed either way.

use super::types::*;

/// The crystal and the reference: REF_DIV2 (R16[4]) = 1 halves the
/// crystal "for Xtal > 24 MHz" ([R820T2] p. 9); the crystal is 28.8 MHz,
/// so f_ref = 14.4 MHz. The sweep ran with REF_DIV2 = 1 and every table
/// here holds for that setting.
pub const XTAL_HZ: f64 = 28800000.0;
pub const REF_DIV2: bool = true;
pub const F_REF_HZ: f64 = 14400000.0;

/// Nint = 4 * Ni2c + Si2c + 13 (R20, [R820T2] p. 9): 13..=268. The sweep
/// covered it in steps of 5.
pub const NINT_RANGE: (u16, u16) = (13, 268);

/// The VCO span over which the documented dividers received the tone:
/// Nint 58..=128 (f_VCO = f_ref * 2 * Nint), with no reception one sweep
/// step
/// outside either end.
pub const VCO_RECEIVED_NINT: (u16, u16) = (58, 128);
pub const VCO_RECEIVED_HZ: (f64, f64) = (1670400000.0, 3686400000.0);

/// The VCO range the driver programs within: `VCO_RECEIVED_HZ` moved
/// 30 MHz inward and rounded inward to 10 MHz (a choice, findings.md
/// step 4c).
pub const VCO_RANGE_HZ: (f64, f64) = (1710000000.0, 3650000000.0);

